source:
(()=>{
/* Bài 2 — Biến và câu lệnh cin (chuẩn tường minh, 19/10/2026)
   Bối cảnh: máy tính tiền của quầy trà sữa lớp mình tại Lễ hội Mùa Xuân.
   Tiết 1 = Chặng 1 (biến, phép gán, phép tính), tiết 2 = Chặng 2 (cin, Nhập → Xử lý → Xuất), cuối tiết 2 = Chặng chứng chỉ.
   Mỗi chặng 6 tab (VAN_PHONG.md): Bối cảnh → Đoán rồi chạy → Kiểm chứng → Ghi nhớ → Luyện tập → Phản tư.
   Chuẩn câu hỏi: có tình huống, hỏi một ý, 4 phương án độ dài gần bằng nhau; mỗi phương án sai là một cách hiểu sai thường gặp.
   Bước chạy có bảng Bộ nhớ (mem); bước cin dùng trường nhap để số người dùng gõ hiện tô vàng như trên Programiz.
*/
"use strict";

const { scratch, boiCanh, bang, ghiVo, luuY, chiTiet, timThem, sauTab, huongDanDoan, bonBuoc, tuCham, kieuDuLieu } = window.KIT;
const strip = code => window.CPP.stripComments(code);

/* ---------- đoạn code dùng xuyên suốt ---------- */
// Chặng 1: máy tính tiền nhớ số ly, giá một ly, rồi tính tổng.
const TIEN = `#include <iostream>
using namespace std;
int main() {
    int soLy = 2;
    int giaLy = 25000;
    int tongTien = soLy * giaLy;
    cout << "So ly: " << soLy << endl;
    cout << "Tong tien: " << tongTien;
    return 0;
}`;
// Lần 2 chỉ khác dòng 8: tên biến bị đặt trong dấu ngoặc kép.
const TIEN_NHAY = TIEN.replace('cout << "Tong tien: " << tongTien;', 'cout << "Tong tien: " << "tongTien";');
const MAN_TIEN = ["So ly: 2\nTong tien: 50000", "So ly: soLy\nTong tien: tongTien", "So ly: 2\nTong tien: tongTien", "So ly: 2\nTong tien: soLy * giaLy"];
// Lần 3: gán lại giá trị (giảm giá 5000).
const GIAM = `#include <iostream>
using namespace std;
int main() {
    int tongTien = 50000;
    tongTien = tongTien - 5000;
    cout << "Phai tra: " << tongTien;
    return 0;
}`;
const MAN_GIAM = ["Phai tra: 45000", "Phai tra: 50000", "Phai tra: tongTien - 5000", "Phai tra: -5000"];
const TRA_DAO_LOI = `#include <iostream>
using namespace std;
int main() {
    int soLy = 3;
    int giaLy = 20000;
    int tongTien = soLy + giaLy;
    cout << "So ly: " << soLy << endl;
    cout << "Tong tien: " << "tongTien";
    return 0;
}`;

// Chặng 2: khách tự nhập số ly.
const NHAP = `#include <iostream>
using namespace std;
int main() {
    int soLy;
    cout << "Nhap so ly: ";
    cin >> soLy;
    int tongTien = soLy * 25000;
    cout << "Tong tien: " << tongTien;
    return 0;
}`;
const manNhap = n => `Nhap so ly: ${n}\nTong tien: ${n * 25000}`;
const luaChonNhap = n => [manNhap(n), `Tong tien: ${n * 25000}`, `Nhap so ly: ${n}\nTong tien: soLy * 25000`, `Nhap so ly: Tong tien: ${n * 25000}`];
const traceNhap = n => [
  { l: 3, why: "Máy bắt đầu chạy từ hàm <code>main()</code>." },
  { l: 4, mem: ["soLy", "int", "?"], why: "Khai báo biến <code>soLy</code> kiểu <code>int</code> nhưng chưa gán giá trị. Giá trị lúc này chưa xác định (ghi là ?), nên chương trình phải nhập trước khi dùng." },
  { l: 5, out: "Nhap so ly: ", why: "In <strong>câu dẫn</strong> để người dùng biết cần gõ gì. Không có <code>endl</code> nên con trỏ đứng ngay sau dấu hai chấm và dấu cách." },
  { l: 6, nhap: String(n), mem: ["soLy", "int", String(n)], why: `Máy dừng lại và chờ. Khách gõ <code>${n}</code> rồi bấm Enter. Số ${n} hiện ngay sau câu dẫn, phím Enter đưa con trỏ xuống dòng, và <code>cin</code> lưu ${n} vào biến <code>soLy</code>.` },
  { l: 7, mem: ["tongTien", "int", String(n * 25000)], why: `Khai báo biến <code>tongTien</code> và gán giá trị <code>soLy * 25000</code> = ${n} × 25000 = ${n * 25000}.` },
  { l: 8, out: `Tong tien: ${n * 25000}`, why: `In chuỗi <code>"Tong tien: "</code>, rồi in giá trị của biến <code>tongTien</code> là ${n * 25000}.` },
  { l: 9, why: "<code>return 0;</code> kết thúc chương trình." }];
const KHONG_DAN = `#include <iostream>
using namespace std;
int main() {
    int soLy;
    cin >> soLy;
    int tongTien = soLy * 25000;
    cout << "Tong tien: " << tongTien;
    return 0;
}`;
const CIN_LOI = `#include <iostream>
using namespace std;
int main() {
    int soLy;
    cout << "Nhap so ly: ";
    cin << soLy;
    cout << "Tong tien: " << soLy * 25000;
    return 0;
}`;
const TRA_DAO_KHUNG = `#include <iostream>
using namespace std;
int main() {
    int soLy;
    // 1. In cau dan "Nhap so ly: " roi nhap soLy

    // 2. Tinh tongTien = soLy * 20000

    // 3. In "Tong tien: " va tongTien

    return 0;
}`;
const HOA_DON_KHUNG = `#include <iostream>
using namespace std;
int main() {
    int soLy, soTopping;
    cout << "Nhap so ly: ";
    cin >> soLy;
    cout << "Nhap so topping: ";
    cin >> soTopping;
    // Tinh va in tong tien o day

    return 0;
}`;
const CHIA_KHUNG = `#include <iostream>
using namespace std;
int main() {
    int tongTien, soNguoi;
    cout << "Nhap tong tien: ";
    cin >> tongTien;
    cout << "Nhap so nguoi: ";
    cin >> soNguoi;
    // Tinh tien moi nguoi va so tien con du

    return 0;
}`;

const BON_BUOC_1 = bonBuoc([["Hiểu đề", "chương trình cần tính gì, in ra những dòng nào?"],
  ["Chọn biến", "mỗi số cần nhớ là một biến kiểu <code>int</code>, đặt tên có nghĩa theo kiểu camelCase."],
  ["Viết màn hình mong đợi trước", "tính tay kết quả, chép ra giấy từng dòng màn hình phải hiện."],
  ["Viết, chạy, so sánh, sửa", "chạy chương trình, so từng chữ, từng con số với màn hình mong đợi rồi sửa chỗ khác."]]);
const BON_BUOC_2 = bonBuoc([["Hiểu đề", "người dùng nhập gì, máy tính gì, in ra gì?"],
  ["Chọn biến", "biến nhận số nhập và biến chứa kết quả, kiểu <code>int</code>, tên có nghĩa."],
  ["Thiết kế test case trước khi viết", "chọn vài số nhập khác nhau và tính tay màn hình mong đợi cho từng số."],
  ["Viết, chạy, so sánh, sửa", "chạy với từng test case, so màn hình với kết quả đã tính tay."]]);

window.LESSON = {
  id: "bai02",
  chuan: 2,
  number: 2,
  title: "Biến và câu lệnh cin",
  story: "Máy tính tiền của quầy trà sữa",
  badge: { icon: "🧮", name: "Người giữ máy tính tiền" },
  skills: ["Khai báo biến int", "Phép gán", "Phép tính + - * / %", "Đặt tên biến", "Câu lệnh cin", "Nhập → Xử lý → Xuất"],
  certNote: "Nộp kèm: ảnh bài làm nhóm và bài cá nhân trên Programiz",

  errorTable: [
    ["Màn hình in ra tên biến thay vì số", "Đặt tên biến trong dấu ngoặc kép: <code>cout &lt;&lt; \"tongTien\";</code>", "Bỏ dấu ngoặc kép: <code>cout &lt;&lt; tongTien;</code>"],
    ["Máy báo không biết tên biến", "Chưa khai báo biến, hoặc gõ sai chữ hoa, chữ thường", "Khai báo trước khi dùng: <code>int soLy;</code>; gõ đúng tên"],
    ["Lỗi cú pháp ở dòng cin", "Viết ngược toán tử: <code>cin &lt;&lt; soLy;</code>", "Nhập dùng <code>cin &gt;&gt; soLy;</code>"],
    ["<code>7 / 2</code> ra 3 chứ không phải 3.5", "Chia hai số nguyên thì máy bỏ phần thập phân", "Muốn lấy số dư thì dùng <code>%</code>"],
    ["Người dùng không biết phải gõ gì", "Thiếu câu dẫn trước <code>cin</code>", "In câu dẫn bằng <code>cout</code> ngay trước <code>cin</code>"],
    ["Máy báo không biết tên “cout”", "Thiếu <code>using namespace std;</code>", "Thêm ngay sau <code>#include &lt;iostream&gt;</code>"]
  ],

  steps: [
    /* ================= CHẶNG 1 · TIẾT 1 · biến và phép tính ================= */
    {
      kind: "stage", id: "stage-1", number: 1, nav: "Chặng 1",
      kicker: "CHẶNG 1 · TIẾT 1 · BIẾN, PHÉP GÁN VÀ PHÉP TÍNH",
      title: "Máy tính tiền biết nhớ số",
      bit: "Chào bạn! Chặng này có 6 phần. Làm xong mỗi phần, bấm <strong>Tiếp</strong> ở cuối trang.",
      objectives: ["Khai báo biến kiểu int và gán giá trị cho biến",
        "Tính tiền bằng phép tính số học, rồi in giá trị của biến",
        "Phân biệt in chữ trong dấu ngoặc kép với in giá trị của biến"],
      flow: [
        { label: "Bối cảnh", title: "Máy tính tiền cần nhớ số ly và giá tiền",
          html: boiCanh("Mỗi ly trà sữa giá 25000 đồng. Một khách mua 2 ly. Máy tính tiền của quầy phải in ra số ly và tổng tiền.",
            `<p>Để tính được, máy phải <strong>nhớ</strong> ba con số: số ly, giá một ly và tổng tiền. Trong lập trình, chỗ để máy nhớ một giá trị gọi là <strong>biến</strong>. Mỗi biến có một <strong>tên</strong> (ví dụ <code>soLy</code>), một <strong>kiểu dữ liệu</strong> (ví dụ <code>int</code> là số nguyên) và một <strong>giá trị</strong> (ví dụ 2).</p>
             <p>Ở chặng này, bạn sẽ đọc ba chương trình tính tiền, đoán màn hình rồi chạy từng dòng để xem giá trị các biến thay đổi thế nào trong bảng <strong>Bộ nhớ</strong>. Sau đó bạn tự sửa hoá đơn trà đào bị tính sai.</p>`) + sauTab("Kiểm chứng") },
        { label: "Đoán rồi chạy", title: "Ba chương trình tính tiền", tasks: ["c1-dc1", "c1-dc2", "c1-dc3"],
          html: huongDanDoan(3), bit: "Nhìn bảng Bộ nhớ: mỗi biến là một ô có tên, kiểu và giá trị." },
        { label: "Kiểm chứng", title: "Biến lưu gì, máy in gì?", tasks: ["c1-dong4", "c1-chubien", "c1-ten"],
          code: TIEN, focus: [4, 6],
          html: `<p>Khung bên trái là chương trình ở <strong>Lần 1</strong>. Dựa vào bảng Bộ nhớ và màn hình bạn vừa thấy khi chạy từng dòng, trả lời các câu hỏi bên cạnh.</p>` },
        { label: "Ghi nhớ", title: "Biến, phép gán và phép tính",
          html: ghiVo(["<code>int tenBien = giaTri;</code>: khai báo biến kiểu số nguyên và gán giá trị ban đầu.",
                "<code>tongTien = tongTien - 5000;</code>: phép gán tính vế phải trước, rồi lưu kết quả vào biến, thay giá trị cũ.",
                "<code>cout &lt;&lt; tongTien;</code> in giá trị của biến; <code>cout &lt;&lt; \"tongTien\";</code> in nguyên văn chữ tongTien."])
            + luuY("phải khai báo biến trước khi dùng. Tên biến phân biệt chữ hoa, chữ thường: <code>tongTien</code> và <code>tongtien</code> là hai biến khác nhau.")
            + chiTiet
            + bang("1. Khái niệm", ["Thuật ngữ", "Định nghĩa", "Ví dụ"], [
              ["Biến", "Vùng nhớ có tên, dùng để lưu một giá trị. Giá trị của biến có thể thay đổi khi chương trình chạy.", "<code>soLy</code>, <code>tongTien</code>"],
              ["Kiểu dữ liệu", "Loại giá trị mà biến được phép lưu. Kiểu quyết định máy cấp bao nhiêu bộ nhớ và tính toán thế nào.", "<code>int</code>"],
              ["<code>int</code>", "Kiểu số nguyên (integer): số không có phần thập phân, có thể âm.", "<code>2</code>, <code>25000</code>, <code>-5</code>"],
              ["Khai báo biến", "Câu lệnh tạo biến mới, gồm kiểu và tên. Biến phải được khai báo trước khi dùng.", "<code>int soLy;</code>"],
              ["Khởi tạo", "Gán giá trị ban đầu ngay lúc khai báo.", "<code>int soLy = 2;</code>"],
              ["Phép gán <code>=</code>", "Tính giá trị ở vế phải, rồi lưu vào biến ở vế trái. Giá trị cũ của biến bị thay. Dấu <code>=</code> không phải phép so sánh.", "<code>tongTien = tongTien - 5000;</code>"]])
            + kieuDuLieu("2. ")
            + bang("3. Phép tính số học với số nguyên", ["Toán tử", "Ý nghĩa", "Ví dụ", "Kết quả"], [
              ["<code>+</code>", "cộng", "<code>7 + 2</code>", "9"],
              ["<code>-</code>", "trừ", "<code>7 - 2</code>", "5"],
              ["<code>*</code>", "nhân", "<code>7 * 2</code>", "14"],
              ["<code>/</code>", "chia lấy phần nguyên: chia hai số nguyên thì máy <strong>bỏ phần thập phân</strong>", "<code>7 / 2</code>", "3"],
              ["<code>%</code>", "chia lấy <strong>số dư</strong>", "<code>7 % 2</code>", "1"]])
            + bang("4. Quy tắc đặt tên biến trong C++", ["Tên", "Hợp lệ?", "Lý do"], [
              ["<code>tongTien</code>", "✅ Hợp lệ", "chỉ gồm chữ cái tiếng Anh, viết liền"],
              ["<code>so_ly</code>", "✅ Hợp lệ", "dấu gạch dưới <code>_</code> được phép"],
              ["<code>diem1</code>", "✅ Hợp lệ", "chữ số đứng sau chữ cái được phép"],
              ["<code>2ly</code>", "❌ Không", "không được bắt đầu bằng chữ số"],
              ["<code>so ly</code>", "❌ Không", "không được có dấu cách"],
              ["<code>sốLy</code>", "❌ Không", "không được có chữ tiếng Việt có dấu"],
              ["<code>int</code>", "❌ Không", "trùng từ khoá của C++"]])
            + bang("5. Hai cách viết tên biến nhiều từ", ["Cách viết", "Quy tắc", "Ví dụ", "Thường gặp ở"], [
              ["<strong>camelCase</strong>", "Viết liền; từ đầu viết thường, mỗi từ sau viết hoa chữ cái đầu (như bướu lạc đà).", "<code>soLy</code>, <code>tongTien</code>, <code>giaMotLy</code>", "Java, JavaScript, nhiều chương trình C++"],
              ["<strong>snake_case</strong>", "Tất cả viết thường, các từ nối bằng dấu gạch dưới <code>_</code> (như con rắn).", "<code>so_ly</code>, <code>tong_tien</code>, <code>gia_mot_ly</code>", "Python, thư viện chuẩn của C++"]])
            + `<p>Cả hai cách đều hợp lệ. Khoá học này dùng <strong>camelCase</strong>. Khi viết chương trình, chọn một cách và dùng thống nhất cho mọi biến.</p>`
            + scratch("set [so ly] to (2)\nsay (join [Tong tien: ] ((so ly) * (25000)))", "Khai báo và gán biến giống khối <em>đặt … thành</em> trong Scratch.")
            + timThem([["https://www.w3schools.com/cpp/cpp_variables.asp", "W3Schools · Biến"],
                       ["https://www.w3schools.com/cpp/cpp_variables_identifiers.asp", "W3Schools · Đặt tên biến"],
                       ["https://www.w3schools.com/cpp/cpp_operators_arithmetic.asp", "W3Schools · Phép tính số học"],
                       ["https://www.learncpp.com/cpp-tutorial/introduction-to-objects-and-variables/", "LearnCpp · Biến"],
                       ["https://www.learncpp.com/cpp-tutorial/keywords-and-naming-identifiers/", "LearnCpp · Từ khoá và tên"]]) },
        { label: "Luyện tập", title: "Chọn kiểu, điền, rồi sửa hoá đơn trà đào", tasks: ["c1-kieu", "c1-dien", "c1-sua"], html: BON_BUOC_1 },
        { label: "Phản tư", title: "Bạn đã chắc đến đâu?", tasks: ["c1-tucham"], stop: true,
          html: `<p>${tuCham}</p>`, bit: "Xong Chặng 1! Dừng lại và nhìn lên bảng." }
      ],
      challenges: [
        { id: "c1-dc1", type: "doanchay", predict: true, icon: "🔮",
          title: "Lần 1 · Tính tiền 2 ly",
          prompt: "Chương trình khai báo 3 biến: số ly, giá một ly và tổng tiền. Dòng 7 và dòng 8 in giá trị của hai biến.",
          ask: "Theo bạn, màn hình sẽ hiện gì?",
          code: TIEN, focus: [6], options: MAN_TIEN, answer: MAN_TIEN[0],
          trace: [
            { l: 3, why: "Máy bắt đầu chạy từ hàm <code>main()</code>." },
            { l: 4, mem: ["soLy", "int", "2"], why: "Khai báo biến <code>soLy</code> kiểu <code>int</code> (số nguyên) và gán giá trị ban đầu là 2. Bảng Bộ nhớ có thêm một ô tên soLy." },
            { l: 5, mem: ["giaLy", "int", "25000"], why: "Khai báo biến <code>giaLy</code> và gán giá trị 25000 (giá một ly)." },
            { l: 6, mem: ["tongTien", "int", "50000"], why: "Máy lấy giá trị của <code>soLy</code> (2) nhân giá trị của <code>giaLy</code> (25000), được 50000, rồi gán vào biến mới <code>tongTien</code>." },
            { l: 7, out: "So ly: 2\n", why: "Chuỗi <code>\"So ly: \"</code> in nguyên văn. <code>soLy</code> nằm ngoài dấu ngoặc kép nên máy in <strong>giá trị</strong> của biến là 2. <code>endl</code> xuống dòng." },
            { l: 8, out: "Tong tien: 50000", why: "Tương tự: in chuỗi <code>\"Tong tien: \"</code>, rồi in giá trị của biến <code>tongTien</code> là 50000." },
            { l: 9, why: "<code>return 0;</code> kết thúc chương trình." }],
          whyRight: "soLy và tongTien nằm ngoài dấu ngoặc kép, nên máy in giá trị đang lưu trong biến: 2 và 50000.",
          why: "soLy và tongTien nằm ngoài dấu ngoặc kép, nên máy in giá trị đang lưu trong biến: 2 và 50000. Máy tính phép nhân ở dòng 6 rồi lưu kết quả, không in phép tính." },
        { id: "c1-dc2", type: "doanchay", predict: true, icon: "🔮", after: "c1-dc1",
          title: "Lần 2 · Chỉ khác dòng 8",
          prompt: "Chương trình này giống Lần 1, chỉ khác ở dòng 8: <code>tongTien</code> được đặt trong dấu ngoặc kép.",
          ask: "Theo bạn, lần này màn hình sẽ hiện gì?",
          code: TIEN_NHAY, focus: [8], options: MAN_TIEN, answer: MAN_TIEN[2],
